// Money received through PayPal, from PayPal's Transaction Search API, called through PayPal's
// TypeScript Server SDK (generated by APIMatic). Only payments of Tanpura invoices are counted,
// matched by PayPal invoice id (other money in the account, e.g. sandbox top-ups, is left out).
// Without PayPal keys, a clearly labelled sample is built from the invoices marked paid.
import { Client, Environment, TransactionSearchController } from '@paypal/paypal-server-sdk';
import type { PaymentRow, PaymentsReport } from '../../shared/api';
import type { Currency } from '../../shared/billing';
import { lastDayOfMonth, wallTimeToIso } from '../../shared/time';
import { config } from './config';
import { convertReceived, homeCurrency } from './fx';
import type { Dataset } from './store';

const CACHE_MS = 60_000;
// PayPal's rows per month, shared by every data copy (each matches its own invoices).
const cache = new Map<string, { at: number; rows: PaymentRow[] }>();

let controller: TransactionSearchController | undefined;
function transactions(): TransactionSearchController {
  if (!config.paypal) throw new Error('PayPal credentials are not set');
  controller ??= new TransactionSearchController(
    new Client({
      clientCredentialsAuthCredentials: { oAuthClientId: config.paypal.clientId, oAuthClientSecret: config.paypal.secret },
      environment: Environment.Sandbox,
      timeout: 20_000,
    }),
  );
  return controller;
}

const round2 = (n: number) => Math.round(n * 100) / 100;
const STATUS: Record<string, string> = { S: 'completed', P: 'pending', V: 'reversed', D: 'denied', F: 'partially refunded' };

async function fromPayPal(data: Dataset, month: string, now: Date): Promise<PaymentRow[]> {
  const tz = data.teacher.timezone;
  // UTC with "Z", seconds included: the documented date format (a month is within the 31-day limit).
  const utc = (ms: number) => new Date(ms).toISOString().replace(/\.\d{3}Z$/, 'Z');
  const startDate = utc(Date.parse(wallTimeToIso(`${month}-01`, '00:00', tz)));
  const monthEnd = Date.parse(wallTimeToIso(lastDayOfMonth(month), '23:59', tz));
  const endDate = utc(Math.min(monthEnd, now.getTime()));
  const rows: PaymentRow[] = [];
  for (let page = 1; page <= 20; page++) {
    const { result } = await transactions().searchTransactions({ startDate, endDate, fields: 'transaction_info,payer_info', pageSize: 500, page });
    for (const t of result.transactionDetails ?? []) {
      const info = t.transactionInfo;
      const gross = Number(info?.transactionAmount?.value ?? 0);
      if (!info?.transactionId || gross <= 0) continue; // payments in only, not fees or payouts
      const fee = Math.abs(Number(info.feeAmount?.value ?? 0));
      rows.push({
        id: info.transactionId,
        date: (info.transactionInitiationDate ?? '').slice(0, 10),
        currency: (info.transactionAmount?.currencyCode ?? 'USD') as Currency,
        gross: round2(gross),
        fee: round2(fee),
        net: round2(gross - fee),
        status: STATUS[info.transactionStatus ?? ''] ?? info.transactionStatus ?? 'unknown',
        invoiceId: info.invoiceId,
        payerEmail: t.payerInfo?.emailAddress,
      });
    }
    if (page >= (result.totalPages ?? 1)) break;
  }
  return rows;
}

// Sample payments for mock mode: one per invoice paid in the month, with an illustrative fee.
const SAMPLE_FIXED_FEE: Record<Currency, number> = { USD: 0.3, GBP: 0.2, CAD: 0.3, AUD: 0.3, NZD: 0.45, SGD: 0.5, EUR: 0.35 };
function sample(data: Dataset, month: string): PaymentRow[] {
  return data.invoices
    .filter((i) => i.status === 'PAID' && !i.refund && i.paidAt?.startsWith(month))
    .map((i) => {
      const fee = round2(i.total * 0.044 + SAMPLE_FIXED_FEE[i.currency]);
      return { id: `SAMPLE-${i.id}`, date: i.paidAt!, currency: i.currency, gross: i.total, fee, net: round2(i.total - fee), status: 'completed', invoiceId: i.id };
    });
}

export async function paymentsReport(data: Dataset, month: string, now: Date): Promise<PaymentsReport> {
  const source = config.paypal ? 'paypal' : 'mock';
  let raw: PaymentRow[];
  let failed: string | undefined;
  const hit = cache.get(month);
  if (config.paypal && hit && Date.now() - hit.at < CACHE_MS) raw = hit.rows;
  else {
    try {
      raw = config.paypal ? await fromPayPal(data, month, now) : sample(data, month);
      if (config.paypal) cache.set(month, { at: Date.now(), rows: raw });
    } catch (e) {
      // Shown on the Payments tab; the rest of the app is unaffected. Not cached, so it retries.
      console.error(e);
      raw = [];
      failed = 'PayPal Transaction Search did not answer just now. Try again in a minute. (It needs "Transaction search" enabled on the PayPal app.)';
    }
  }

  // Only payments of this teacher's own invoices count.
  const invoices = new Map(data.invoices.map((i) => [i.id, i]));
  const names = new Map(data.students.map((s) => [s.id, s.name]));
  const all = raw.map((r) => {
    const studentId = (r.invoiceId && invoices.get(r.invoiceId)?.studentId) || undefined;
    return { ...r, studentId, studentName: studentId ? names.get(studentId) : undefined };
  });
  const rows = all.filter((r) => r.studentId).sort((a, b) => b.date.localeCompare(a.date));

  const totals = new Map<Currency, { currency: Currency; gross: number; fee: number; net: number }>();
  for (const r of rows) {
    const t = totals.get(r.currency) ?? { currency: r.currency, gross: 0, fee: 0, net: 0 };
    t.gross = round2(t.gross + r.gross);
    t.fee = round2(t.fee + r.fee);
    t.net = round2(t.net + r.net);
    totals.set(r.currency, t);
  }
  const report: PaymentsReport = {
    source,
    month,
    rows,
    totals: [...totals.values()],
    unmatched: all.length - rows.length,
    home: await convertReceived(rows.filter((r) => r.status === 'completed'), homeCurrency(data.teacher.country)),
    note: failed
      ? failed
      : source === 'mock'
        ? 'Sample data: no PayPal keys, so these are the invoices marked paid, with an illustrative fee.'
        : 'From PayPal Transaction Search. New payments can take up to 3 hours to appear here.',
  };
  return report;
}

export const clearPaymentsCache = () => cache.clear();
